import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers, selectors } from 'kea'
import { loaders } from 'kea-loaders'

import { organizationLogic } from 'scenes/organizationLogic'

import type { OrganizationType } from '~/types'

import * as api from '../generated/api'
import type { PartnerPayerApplicationApi } from '../generated/api.schemas'
import { partnerBillingErrorMessage } from './partnerBillingErrors'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface partnerBillingApplicationsLogicValues {
    currentOrganizationId: string // organizationLogic
    isAdminOrOwner: boolean | null // organizationLogic
    partnerBillingApplications: PartnerPayerApplicationApi[] | null
    partnerBillingApplicationsError: string | null
    partnerBillingApplicationsLoading: boolean
    selectedApplication: PartnerPayerApplicationApi | null
    selectedApplicationId: string | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface partnerBillingApplicationsLogicActions {
    loadCurrentOrganizationSuccess: (
        currentOrganization: OrganizationType | null,
        payload?: any
    ) => {
        currentOrganization: OrganizationType | null
        payload?: any
    } // organizationLogic
    loadPartnerBillingApplications: () => any
    loadPartnerBillingApplicationsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadPartnerBillingApplicationsSuccess: (
        partnerBillingApplications: PartnerPayerApplicationApi[],
        payload?: any
    ) => {
        partnerBillingApplications: PartnerPayerApplicationApi[]
        payload?: any
    }
    selectApplication: (applicationId: string) => {
        applicationId: string
    }
}

export type partnerBillingApplicationsLogicType = MakeLogicType<
    partnerBillingApplicationsLogicValues,
    partnerBillingApplicationsLogicActions
>

export const partnerBillingApplicationsLogic = kea<partnerBillingApplicationsLogicType>([
    path(['products', 'billing', 'frontend', 'partnerBilling', 'partnerBillingApplicationsLogic']),
    connect(() => ({
        values: [organizationLogic, ['currentOrganizationId', 'isAdminOrOwner']],
        actions: [organizationLogic, ['loadCurrentOrganizationSuccess']],
    })),
    actions({
        selectApplication: (applicationId: string) => ({ applicationId }),
    }),
    loaders(({ values }) => ({
        partnerBillingApplications: [
            null as PartnerPayerApplicationApi[] | null,
            {
                loadPartnerBillingApplications: async () => {
                    return await api.partnerBillingList(values.currentOrganizationId)
                },
            },
        ],
    })),
    reducers({
        selectedApplicationId: [
            null as string | null,
            {
                selectApplication: (_, { applicationId }) => applicationId,
            },
        ],
        partnerBillingApplicationsError: [
            null as string | null,
            {
                loadPartnerBillingApplications: () => null,
                loadPartnerBillingApplicationsSuccess: () => null,
                loadPartnerBillingApplicationsFailure: (_, { errorObject }) => partnerBillingErrorMessage(errorObject),
            },
        ],
    }),
    selectors({
        selectedApplication: [
            (s) => [s.partnerBillingApplications, s.selectedApplicationId],
            (
                partnerBillingApplications: PartnerPayerApplicationApi[] | null,
                selectedApplicationId: string | null
            ): PartnerPayerApplicationApi | null =>
                partnerBillingApplications?.find((application) => application.id === selectedApplicationId) ??
                partnerBillingApplications?.[0] ??
                null,
        ],
    }),
    listeners(({ actions, values }) => ({
        // Without an organization in the page context, the membership level arrives after this logic mounts.
        loadCurrentOrganizationSuccess: () => {
            if (
                values.isAdminOrOwner &&
                values.partnerBillingApplications === null &&
                !values.partnerBillingApplicationsLoading
            ) {
                actions.loadPartnerBillingApplications()
            }
        },
    })),
    afterMount(({ actions, values }) => {
        // The list is admin-only, so asking for it as a member only produces a 403.
        if (values.isAdminOrOwner) {
            actions.loadPartnerBillingApplications()
        }
    }),
])
